var DX_BODY = window.DX_BODY || {};

/* ==================== الكلية والمجرى البولي ==================== */

DX_BODY['pyelonephritis'] = {
  symptoms: {
    ar: 'يبدأ غالباً بما يشبه التهاب المثانة: حرقة عند التبوّل وإلحاح وتكرار. ثم يتغيّر المشهد خلال يوم أو يومين، فترتفع الحرارة مع رجفة تهزّ الجسم، ويظهر ألم في الخاصرة أو أسفل الظهر من جهة واحدة يزداد بالطرق الخفيف عليها، مع غثيان وقيء وإرهاق يُقعد صاحبه عن يومه. والبول قد يصير عكراً كريه الرائحة أو مخلوطاً بدم. وما ينبغي الانتباه له أن الصورة ليست واحدة عند الجميع: كبار السنّ قد لا ترتفع حرارتهم أصلاً وإنما يظهر عليهم تشوّش ذهني أو ضعف مفاجئ وسقوط، والحوامل والسكّريون قد يتدهورون أسرع مما توحي به شكواهم، والرضّع قد لا يكون عندهم إلا حمّى وقيء ورفض الرضاعة بلا أي علامة بولية.',
    en: 'It usually begins like a bladder infection: burning on passing urine, urgency and frequency. Then within a day or two the picture changes, the temperature rises with shaking chills, and a pain appears in one flank or the lower back that worsens when the area is lightly tapped, with nausea, vomiting and an exhaustion that stops the day. The urine may turn cloudy and foul-smelling or be mixed with blood. What deserves attention is that the picture is not the same in everyone: older people may not run a fever at all but instead become confused or suddenly weak and fall, pregnant women and diabetics may deteriorate faster than their complaint suggests, and infants may have nothing but fever, vomiting and refusal to feed, with no urinary sign at all.'
  },
  cause: {
    ar: 'الأصل أن جراثيم من محيط الشرج تصعد الإحليل إلى المثانة، فإن لم تُوقف واصلت صعودها في الحالب حتى تبلغ حويضة الكلية ثم نسيجها، وأشيعها الإشريكية القولونية. ويزيد احتمال هذا الصعود كل ما يعوق جريان البول أو يفتح الطريق أمام الجراثيم: حصاة عالقة في الحالب، وتضخّم البروستاتا الذي يبقي بولاً راكداً في المثانة، وارتداد البول من المثانة نحو الكلية عند الأطفال، والقسطرة البولية، والحمل لأن هرموناته ترخي الحالبين ويضغط عليهما الرحم المتضخّم. ويضاعفه السكّري لأن السكّر في البول وسط صالح لنموّ الجراثيم ولأن المناعة أضعف. ويسهّله أيضاً قلة شرب الماء وحبس البول طويلاً وتكرار التهابات المثانة بلا علاج كامل.',
    en: 'Germs from around the anus climb the urethra into the bladder, and if they are not stopped they continue up the ureter to reach the renal pelvis and then the kidney tissue itself, the commonest being Escherichia coli. Anything that obstructs the flow of urine or opens the road to germs increases this climb: a stone stuck in the ureter, an enlarged prostate that leaves stagnant urine in the bladder, reflux of urine from the bladder back toward the kidney in children, a urinary catheter, and pregnancy, whose hormones relax the ureters while the enlarged womb presses on them. Diabetes doubles the risk, because sugar in the urine is a good medium for growth and because immunity is weaker. Drinking too little, holding urine for long hours and repeated partly treated bladder infections all make it easier.'
  },
  diagnosis: {
    ar: 'يبدأ بتحليل البول الذي يُظهر كريات بيضاء ونتريت وجراثيم، ثم بزرع البول وهو الفحص الحاسم لأنه يسمّي الجرثومة نفسها ويقول أي المضادات تقتلها وأيها صارت مقاومة له، ولهذا يُسحب قبل بدء العلاج لا بعده. وتُطلب تحاليل دم لعدد الكريات البيضاء ولوظائف الكلى ولمؤشرات الالتهاب لتقدير شدّة الحالة، ويُزرع الدم أيضاً إذا كانت الحمّى عالية أو الحالة متدهورة للتأكد أن الجراثيم لم تدخل مجرى الدم. والتصوير ليس ضرورياً في كل حالة، لكنه يصير لازماً إن لم تتحسّن الحمّى خلال يومين أو ثلاثة أو كانت هناك حصى سابقة أو كلية واحدة، فتُطلب موجات صوتية أو أشعة مقطعية للبحث عن انسداد يمنع خروج القيح أو عن خرّاج تكوّن داخل الكلية.',
    en: 'It starts with a urine test showing white cells, nitrites and bacteria, then a urine culture, which is the decisive test because it names the germ itself and says which antibiotics kill it and which it has become resistant to, which is why it is taken before treatment begins rather than after. Blood tests are requested for the white cell count, kidney function and inflammatory markers to judge severity, and blood cultures are added if the fever is high or the condition is deteriorating, to be sure the germs have not entered the bloodstream. Imaging is not needed in every case, but it becomes necessary if the fever does not settle within two or three days, or if there are previous stones or a single kidney, and then ultrasound or a CT scan is used to look for an obstruction preventing pus from draining, or an abscess that has formed inside the kidney.'
  },
  treatment: {
    ar: 'العلاج مضاد حيوي يختاره الطبيب على أساس نتيجة الزرع وأنماط المقاومة في المنطقة، ويُعطى في الوريد داخل المستشفى إذا منع القيء الشرب أو كانت المريضة حاملاً أو كانت الحالة متدهورة أو الكلية واحدة، وبالفم في البيت إذا كانت الصورة خفيفة والمريض قادراً على الشرب. ويُضاف إليه ترطيب جيّد وخافض للحرارة ومسكّن. والنقطة التي لا يُتساهل فيها أن المضاد وحده لا يشفي كلية مسدودة: إن وُجد انسداد فلا بدّ من تصريف البول عاجلاً بدعامة في الحالب أو أنبوب يُدخل إلى الكلية عبر الظهر، وإلا بقي القيح محبوساً وانتقل الإنتان إلى الدم. وإن تكوّن خرّاج فقد يحتاج تفريغاً. ثم يُبحث بعد الشفاء عن سبب يمكن إصلاحه حتى لا تتكرّر النوبة.',
    en: 'Treatment is an antibiotic chosen by the doctor on the basis of the culture result and local resistance patterns, given intravenously in hospital if vomiting prevents drinking, if the patient is pregnant, if the condition is deteriorating or if there is a single kidney, and by mouth at home if the picture is mild and the patient can drink. Good hydration, something to lower the fever and pain relief are added. The point on which there is no compromise is that an antibiotic alone does not cure a blocked kidney: if an obstruction is present the urine must be drained urgently, with a stent in the ureter or a tube passed into the kidney through the back, otherwise the pus stays trapped and the infection passes into the blood. An abscess may need draining. After recovery a correctable cause is looked for so the attack does not return.'
  },
  seeDoctor: {
    ar: 'اذهب إلى الطوارئ في يومك إذا اجتمعت حمّى ورجفة مع ألم في الخاصرة، أو إذا منعك القيء من شرب الماء وابتلاع الدواء. واطلب الإسعاف فوراً إذا صحب ذلك تشوّش أو نعاس شديد، أو نبض سريع مع برودة الأطراف ودوخة عند الوقوف، أو قلّ البول قلّة واضحة أو انقطع، فهذه علامات إنتان في الدم أو كلية مسدودة ولا تحتمل تأجيلاً إلى الصباح. والحامل التي تشكو حرقة بول مع حمّى تُقيَّم في اليوم نفسه ولا تُعالج بالانتظار. والرضيع الذي ترتفع حرارته بلا سبب واضح يُفحص بوله. وإن بدأت المضاد الحيوي ولم تنزل الحمّى خلال يومين إلى ثلاثة فارجع للطبيب، فهذا يعني إمّا جرثومة مقاومة وإمّا انسداداً أو خرّاجاً يحتاج تدخّلاً. أما التهابات المثانة المتكرّرة فموعد عادي لبحث سببها.',
    en: 'Go to the emergency department the same day if fever and chills come together with flank pain, or if vomiting stops you drinking water and swallowing medicine. Call an ambulance at once if this is joined by confusion or deep drowsiness, a fast pulse with cold hands and feet and dizziness on standing, or if the urine becomes clearly scanty or stops, because these are signs of blood infection or a blocked kidney and cannot wait until morning. A pregnant woman with burning urine and fever is assessed the same day and never treated by waiting. An infant with unexplained fever should have the urine tested. If you have started an antibiotic and the fever has not fallen within two to three days, return to the doctor, as this means either a resistant germ or an obstruction or abscess needing intervention. Repeated bladder infections deserve an ordinary appointment to find the cause.'
  },
  updated: '2026-09-08'
};

DX_BODY['aki'] = {
  symptoms: {
    ar: 'أول ما يلاحَظ عادةً قلّة البول: مرّات أقلّ وكمية أقلّ ولون أغمق، وقد ينقطع تقريباً. ثم يبدأ الجسم يحتفظ بالماء فتتورّم القدمان والساقان وأحياناً الوجه، ويزيد الوزن بسرعة لا تفسّرها الأكلة، وقد يضيق النفَس عند الاستلقاء لأن السائل يتجمّع في الرئتين. ويرافق ذلك إرهاق وغثيان وفقدان شهية وطعم معدني في الفم وحكّة، ومع ارتفاع الفضلات في الدم يصير التركيز صعباً ويظهر نعاس وتشوّش وربما رجفة أو تشنّج. وأخطر ما في هذه الحالة أن كثيراً منها لا يُشعِر صاحبه بشيء أصلاً في بدايته، ولا يُكتشف إلا في تحليل دم طُلب لسبب آخر — ولهذا تُفحص وظائف الكلى بعد كل نوبة جفاف أو عملية أو دواء جديد ثقيل على الكلية.',
    en: 'The first thing usually noticed is a fall in urine: fewer times, smaller amounts, a darker colour, and it may almost stop. The body then holds water, so the feet and legs and sometimes the face swell, weight rises faster than food explains, and breathing may tighten on lying down because fluid gathers in the lungs. With this come exhaustion, nausea, loss of appetite, a metallic taste and itching, and as waste products rise in the blood concentration becomes hard, with drowsiness, confusion and sometimes tremor or a fit. The most dangerous feature is that many cases cause no sensation at all at the start and are only discovered on a blood test requested for another reason, which is why kidney function is checked after any episode of dehydration, any operation, or any new medicine that is hard on the kidney.'
  },
  cause: {
    ar: 'تُقسَم الأسباب ثلاثة أقسام يفيد فهمها لأن كلاً منها يُعالَج على نحو مختلف. الأول أن الدم قلّ عن الكليتين: جفاف شديد من إسهال أو قيء أو حرّ، أو نزف، أو هبوط ضغط في صدمة أو إنتان، أو قصور قلب. والثاني أذى مباشر لنسيج الكلية: أدوية معروفة بثقلها على الكلية كبعض المضادات ومضادات الالتهاب غير الستيرويدية إذا أُخذت مع الجفاف، وصبغة الأشعة عند من كليتاه ضعيفتان أصلاً، وانحلال عضلي بعد إصابة أو مجهود شديد، والتهاب في الكبيبات. والثالث انسداد المخرج: حصاة في كليتين أو في كلية وحيدة، أو تضخّم بروستاتا يمنع تفريغ المثانة، أو ورم يضغط الحالبين. ويزيد الخطر في كل الأقسام كِبَر السنّ والسكّري والقصور الكلوي المزمن السابق.',
    en: 'The causes fall into three groups, and understanding them helps because each is managed differently. The first is that blood reaching the kidneys has fallen: severe dehydration from diarrhoea, vomiting or heat, bleeding, low blood pressure in shock or sepsis, or heart failure. The second is direct injury to the kidney tissue: medicines known to be hard on the kidney, such as certain antibiotics and anti-inflammatory painkillers taken while dehydrated, contrast dye in someone whose kidneys are already weak, muscle breakdown after injury or extreme exertion, and inflammation of the filtering units. The third is obstruction of the outflow: a stone affecting both kidneys or a single kidney, an enlarged prostate preventing the bladder from emptying, or a tumour pressing on the ureters. In all three groups the risk rises with age, diabetes and pre-existing chronic kidney disease.'
  },
  diagnosis: {
    ar: 'الحكم يقوم على تحليل دم يقيس الكرياتينين واليوريا، والمهمّ فيه ليس الرقم وحده بل مقارنته بقياس سابق للمريض نفسه، لأن ارتفاعاً سريعاً خلال أيام هو ما يميّز الحادّ عن المزمن. ويُقاس معه الصوديوم والبوتاسيوم لأن ارتفاع البوتاسيوم هو الخطر الأقرب على القلب، وتُقاس درجة حموضة الدم. ويُتابَع إدرار البول بالساعة، وقد تُوضع قسطرة لقياسه بدقة. ويُحلَّل البول بحثاً عن بروتين ودم وأسطوانات خلوية تدلّ على أذى في نسيج الكلية نفسه. والموجات الصوتية فحص أساسي ومبكّر لأنها تجيب عن السؤال الحاسم: هل هناك انسداد؟ فإن كان، فالحلّ تصريف لا دواء. وتُراجَع قائمة أدوية المريض كاملة لأن كثيراً من الحالات دواء يمكن إيقافه.',
    en: 'The judgement rests on a blood test measuring creatinine and urea, and what matters is not the number alone but its comparison with an earlier result for the same person, because a rapid rise over days is what separates acute from chronic. Sodium and potassium are measured with it, since a high potassium is the nearest threat to the heart, and the acidity of the blood is checked. Urine output is followed hour by hour, and a catheter may be placed to measure it accurately. The urine is examined for protein, blood and cellular casts that point to damage in the kidney tissue itself. Ultrasound is an early and essential test because it answers the decisive question: is there an obstruction? If there is, the answer is drainage rather than medicine. The full list of the patient medicines is reviewed, because many cases are a drug that can be stopped.'
  },
  treatment: {
    ar: 'المبدأ أن الكلية لا تُعالَج مباشرةً وإنما يُزال ما آذاها ويُدعم الجسم حتى تتعافى، وأكثر الحالات ترجع فعلاً إن أُدركت باكراً. فيُعوَّض السائل بحساب دقيق إن كان السبب جفافاً أو نزفاً، ويُرفع الضغط ويُعالج الإنتان إن كان هبوط الدورة هو السبب، وتُوقف كل الأدوية المؤذية للكلية وتُعدَّل جرعات الباقي بحسب مستوى الوظيفة. وإن كان السبب انسداداً فالتصريف عاجل بقسطرة أو دعامة أو أنبوب في الكلية. ويُراقب البوتاسيوم ويُخفَّض إن ارتفع لأنه يوقف القلب. ويُضبط الملح والسوائل والبروتين في الغذاء بإشراف اختصاصي تغذية. وإذا لم تكف هذه التدابير وتراكمت السموم أو السوائل أو البوتاسيوم بصورة خطرة، فالغسيل الكلوي إجراء مؤقّت يسند الجسم ريثما تستعيد الكلية عملها، لا حكم بالغسيل مدى الحياة.',
    en: 'The principle is that the kidney is not treated directly; rather what harmed it is removed and the body is supported until it recovers, and most cases do recover if caught early. Fluid is replaced by careful calculation if the cause was dehydration or bleeding, blood pressure is restored and infection treated if a failing circulation was the cause, and every medicine that is hard on the kidney is stopped while the doses of the rest are adjusted to the level of function. If the cause is obstruction, drainage is urgent, by catheter, stent or a tube into the kidney. Potassium is watched and lowered if it rises, because it can stop the heart. Salt, fluid and protein in the diet are set with a dietitian. If these measures are not enough and toxins, fluid or potassium build up dangerously, dialysis is a temporary support while the kidney regains its work, not a sentence to lifelong dialysis.'
  },
  seeDoctor: {
    ar: 'اطلب الإسعاف فوراً إذا انقطع البول تقريباً ليوم كامل، أو صحب قلّته ضيق نفس أو ألم صدر أو خفقان أو نعاس شديد وتشوّش أو تشنّج، فهذه صورة تراكم سوائل أو ارتفاع بوتاسيوم يهدّد القلب. واذهب للطوارئ في يومك إذا قلّ البول قلّة واضحة بعد إسهال أو قيء أو حرّ شديد ولم يرجع مع الشرب، أو إذا تورّمت الساقان بسرعة وزاد الوزن كيلوات في أيام. ومن كان عنده سكّري أو قصور كلوي أو قلبي فليطلب تقييماً مبكّراً في أي نوبة جفاف بدل انتظار العلامات. وراجع طبيبك قبل بدء أي مسكّن مضاد للالتهاب إن كانت كليتك ضعيفة أو كنت في يوم مرض وجفاف — فهذا من أشيع أسباب التدهور المفاجئ وأسهلها اجتناباً. وبعد أي نوبة، اطلب إعادة فحص وظائف الكلى للتأكد أنها رجعت.',
    en: 'Call an ambulance at once if urine has almost stopped for a whole day, or if the small output is joined by breathlessness, chest pain, palpitations, deep drowsiness with confusion, or a fit, because this is the picture of fluid overload or a potassium level that threatens the heart. Go to the emergency department the same day if urine falls clearly after diarrhoea, vomiting or severe heat and does not return with drinking, or if the legs swell quickly and weight rises by several kilograms in days. Anyone with diabetes, kidney or heart disease should ask for early assessment in any episode of dehydration rather than waiting for signs. Ask your doctor before starting any anti-inflammatory painkiller if your kidneys are weak or you are ill and dehydrated, since this is among the commonest and most avoidable causes of sudden deterioration. After any episode, ask for kidney function to be rechecked to be sure it has returned.'
  },
  updated: '2026-09-08'
};

DX_BODY['pkd'] = {
  symptoms: {
    ar: 'يمضي المرض صامتاً سنوات طويلة، وكثير من المصابين يعرفون به أول مرة من ارتفاع ضغط دم مبكّر في الثلاثينات بلا سبب ظاهر، أو من صورة أُخذت لسبب آخر. ثم تبدأ الشكوى مع كِبَر الكيسات: ثقل أو ألم ممتدّ في الخاصرتين أو أسفل الظهر، وإحساس بامتلاء البطن لأن الكليتين تكبران حتى تُحسّا باليد، ونوبات ألم حادّ إن نزفت كيسة أو التهبت أو تكوّنت حصاة. ويظهر الدم في البول أحياناً بلا ألم ويخيف صاحبه. وتتكرّر التهابات المسالك ويصعب علاجها لأن الجراثيم تختبئ داخل الكيسات. ومع تقدّم السنين تظهر علامات ضعف الكلية: إرهاق وشحوب وقلّة شهية وتورّم. وقد يشكو بعضهم صداعاً غير معتاد، وهو ما يستحقّ انتباهاً لارتباط المرض بتمدّدات في شرايين الدماغ.',
    en: 'The disease passes silently for many years, and many people first learn of it from early high blood pressure in their thirties with no visible cause, or from a scan taken for another reason. Complaints begin as the cysts enlarge: heaviness or a dragging pain in both flanks or the lower back, a sense of fullness in the abdomen because the kidneys grow until they can be felt by hand, and attacks of sharp pain when a cyst bleeds or becomes infected or a stone forms. Blood sometimes appears in the urine without pain and frightens the person. Urinary infections recur and are hard to clear because germs hide inside the cysts. As the years pass, signs of failing kidneys appear: fatigue, pallor, poor appetite and swelling. Some complain of an unusual headache, which deserves attention because the disease is linked with swellings in the brain arteries.'
  },
  cause: {
    ar: 'مرض وراثي في المقام الأول: طفرة في أحد جينين مسؤولين عن بناء الأنابيب الكلوية تجعل خلايا الأنبوب تنقسم وتفرز سائلاً في مواضع لا ينبغي أن تفعل، فتنشأ جيوب صغيرة تنتفخ ببطء وتنفصل عن الأنبوب حتى تصير كيسات مستقلّة تكبر مدى العمر. والنمط الشائع سائد، أي أن نسخة معطوبة واحدة من أحد الأبوين تكفي، ولذلك يُرى المرض في أجيال متتابعة من العائلة نفسها ويُصيب نحو نصف الأبناء. وهناك نمط أندر متنحٍّ يظهر في الرضاعة ويكون أشدّ. والكيسات لا تقتصر على الكليتين، فأكثر المصابين تنشأ عندهم كيسات في الكبد لا تؤذي وظيفته غالباً، وقد ترافقها تمدّدات في شرايين الدماغ وضعف في صمّام القلب وفتوق في جدار البطن. وسرعة التدهور تتفاوت بين العائلات وبين الأفراد، ويعجّلها ارتفاع الضغط غير المضبوط والتدخين.',
    en: 'It is first of all an inherited disease: a mutation in one of two genes responsible for building the kidney tubules makes tubule cells divide and secrete fluid where they should not, so small pockets form, swell slowly and separate from the tubule until they become independent cysts that grow lifelong. The common form is dominant, meaning a single faulty copy from one parent is enough, which is why the disease is seen in successive generations of the same family and affects about half the children. There is a rarer recessive form that appears in infancy and is more severe. The cysts are not confined to the kidneys: most patients develop liver cysts that usually do not harm its function, and there may also be swellings in the brain arteries, a weak heart valve and hernias in the abdominal wall. The speed of decline varies between families and individuals, and is hastened by uncontrolled blood pressure and by smoking.'
  },
  diagnosis: {
    ar: 'الموجات الصوتية هي الفحص الأول وهي كافية في أكثر الحالات، إذ تُظهر عدد الكيسات في كل كلية، ويُقرأ العدد بحسب عمر الشخص لأن ما يُعدّ كثيراً في العشرين قليل في الخمسين. والرنين المغناطيسي أدقّ في عدّ الكيسات الصغيرة وقياس حجم الكليتين، وقياس الحجم مفيد لأنه يتنبّأ بسرعة التدهور أكثر من تحليل الدم في المراحل الأولى. وتُتابع وظائف الكلى بالكرياتينين وتقدير الترشيح، ويُفحص البول للبروتين والدم، ويُقاس ضغط الدم بانتظام لأنه أول ما يرتفع. والفحص الجيني يُطلب في حالات بعينها: عند الشكّ في صورة غير واضحة، أو عند تقييم متبرّع من العائلة قبل التبرّع بكلية. ويُبحث عن تمدّدات شرايين الدماغ بتصوير الأوعية عند من عنده تاريخ عائلي بنزف دماغي أو أعراض توحي بذلك، لا عند كل مصاب.',
    en: 'Ultrasound is the first test and is enough in most cases, showing the number of cysts in each kidney; the count is read against the age of the person, because what counts as many at twenty is few at fifty. MRI is more accurate for counting small cysts and measuring kidney volume, and volume is useful because it predicts the speed of decline better than blood tests do in the early stages. Kidney function is followed with creatinine and estimated filtration, the urine is checked for protein and blood, and blood pressure is measured regularly because it is the first thing to rise. Genetic testing is requested in particular situations: when the picture is unclear, or when assessing a family member before donating a kidney. Brain arteries are imaged in those with a family history of brain haemorrhage or suggestive symptoms, not in every patient.'
  },
  treatment: {
    ar: 'لا يوجد ما يزيل الكيسات، والهدف إبطاء التدهور وحماية ما بقي من نسيج عامل، وهذا ممكن فعلاً إذا بدأ باكراً. وأهمّ تدبير على الإطلاق ضبط ضغط الدم بدقّة وإلى هدف منخفض يحدّده الطبيب، بأدوية من فئة معيّنة تحمي الكلية إضافةً إلى خفض الضغط، لأن الضغط غير المضبوط هو أسرع ما يستهلك الكلية. ويُنصح بشرب ماء وافر على مدار اليوم وبتقليل الملح تقليلاً حقيقياً وبالابتعاد عن التدخين وعن مضادات الالتهاب غير الستيرويدية. وصار متاحاً في حالات مختارة سريعة التدهور دواء يبطئ نموّ الكيسات يقرّره اختصاصي الكلى ويحتاج متابعة دقيقة لأنه يزيد إدرار البول ويتطلّب مراقبة الكبد. وتُعالج المضاعفات كلٌّ بحسبه: التهاب الكيسة، والحصى، والألم المزمن. وحين تصل الكلية إلى القصور النهائي فالخياران الغسيل أو زراعة كلية، والزراعة نتائجها جيدة في هذا المرض.',
    en: 'Nothing removes the cysts, and the aim is to slow the decline and protect the working tissue that remains, which is genuinely possible if started early. The single most important measure is precise blood pressure control to a low target set by the doctor, using a class of medicines that protects the kidney as well as lowering pressure, because uncontrolled pressure is what consumes the kidney fastest. Ample water through the day is advised, along with a real reduction in salt and avoidance of smoking and of anti-inflammatory painkillers. For selected patients with rapid decline there is now a medicine that slows cyst growth, decided by a kidney specialist and needing close follow-up because it greatly increases urine output and requires liver monitoring. Complications are treated each in its own way: an infected cyst, stones, and chronic pain. When the kidneys reach end stage, the choices are dialysis or transplantation, and transplant results in this disease are good.'
  },
  seeDoctor: {
    ar: 'اطلب الإسعاف فوراً إذا جاءك صداع مفاجئ شديد لم تعرف مثله في حياتك، أو صحبه تقيّؤ أو تصلّب رقبة أو زغللة أو ضعف في جهة، فهذه صورة نزف من تمدّد شرياني في الدماغ وهي أخطر ما يرتبط بهذا المرض. واذهب للطوارئ إذا اجتمعت حمّى ورجفة مع ألم في الخاصرة، أو ظهر دم غزير في البول مع تجلّطات أو ألم لا يُحتمل. وراجع طبيبك في موعد قريب إذا ارتفع ضغطك، أو تكرّر التهاب المسالك، أو زاد ألم الخاصرة المزمن، أو نقص إدرارك أو تورّمت قدماك. ومن كان في عائلته هذا المرض فالمعقول أن يقيس ضغطه بانتظام من شبابه وأن يسأل طبيبه متى يُفحص، خصوصاً قبل الزواج أو قبل التفكير في التبرّع بكلية لقريب، ولا داعي لأن يستعجل فحص أطفاله قبل مشورة مختصّ.',
    en: 'Call an ambulance at once for a sudden severe headache unlike any you have known, especially with vomiting, a stiff neck, blurred vision or weakness on one side, because this is the picture of bleeding from a swelling in a brain artery, the most dangerous association of this disease. Go to the emergency department if fever and chills come with flank pain, or if heavy blood with clots appears in the urine, or the pain is unbearable. See your doctor soon if your blood pressure rises, urinary infections recur, chronic flank pain increases, your urine output falls or your feet swell. Anyone with this disease in the family should reasonably check blood pressure regularly from young adulthood and ask the doctor when to be screened, particularly before marriage or before considering donating a kidney to a relative; there is no need to rush to test children before specialist advice.'
  },
  updated: '2026-09-08'
};

DX_BODY['glomerular-disease'] = {
  symptoms: {
    ar: 'للمصفاة الكلوية شكوتان مختلفتان. الأولى تسريب البروتين: يستيقظ المريض ووجهه وجفناه منتفخان ثم يتحوّل التورّم إلى الساقين والقدمين مع مضيّ اليوم، ويصير البول كثير الرغوة كأن صابوناً فيه، ويزيد الوزن سريعاً من الماء المحتبس، وقد ينتفخ البطن ويضيق النفَس. وهذه صورة شائعة عند الأطفال ويظنّها الأهل حساسية في الوجه. والثانية التهاب المصفاة: يصير البول لون الشاي أو الكولا أو يظهر فيه دم صريح، وترتفع ضغط الدم أحياناً بلا سابقة، ويقلّ البول، ويظهر تورّم أخفّ حول العينين، مع إرهاق وألم في الخاصرة. وكثيراً ما تسبقها التهاب حلق أو جلد بأسبوع أو أسبوعين. والمشترك بينهما أن البداية قد تكون خفيّة، وأن أول دليل يكون تحليل بول عابر.',
    en: 'The kidney filter has two different complaints. The first is protein leak: the person wakes with a puffy face and eyelids, the swelling moves to the legs and feet as the day passes, the urine becomes very frothy as though soapy, weight rises quickly from retained water, and the abdomen may swell and breathing tighten. This picture is common in children and parents often mistake it for a facial allergy. The second is inflammation of the filter: the urine turns the colour of tea or cola or contains frank blood, blood pressure sometimes rises with no previous history, urine output falls, there is milder swelling around the eyes, with fatigue and flank pain. Often a throat or skin infection preceded it by one or two weeks. What both share is that the onset may be hidden, and that the first evidence is a routine urine test.'
  },
  cause: {
    ar: 'الكبيبة مصفاة دقيقة تسمح بمرور الماء والفضلات وتمنع مرور البروتينات وكريات الدم. فإذا تلف حاجزها تسرّب البروتين وخرج مع البول، ونقص بروتين الدم فلم يعد يمسك الماء داخل الأوعية فرشح إلى الأنسجة وظهر التورّم. وإذا التهبت الكبيبة نفسها ضاق مجراها ونزفت فظهر الدم واحتُبس الملح فارتفع الضغط. وأشيع ما يقف خلف ذلك عند الكبار السكّري وارتفاع الضغط المزمن، وعند الأصغر أمراض مناعية ذاتية كالذئبة، أو ردّ فعل مناعي بعد عدوى بكتيرية في الحلق أو الجلد، أو ترسّب أجسام مناعية في الكلية. وقد تسبّبه بعض العدوى الفيروسية المزمنة وبعض الأدوية والسموم، وقد يكون وراثياً. وفي أطفال كثيرين يكون التغيّر في المصفاة دقيقاً لا يظهر إلا بالمجهر الإلكتروني ويستجيب للعلاج استجابةً ممتازة.',
    en: 'The glomerulus is a fine filter that lets water and waste through and holds back proteins and blood cells. If its barrier is damaged, protein leaks into the urine, blood protein falls so water is no longer held inside the vessels and seeps into the tissues as swelling. If the glomerulus itself becomes inflamed, its channel narrows and bleeds, so blood appears, salt is retained and pressure rises. The commonest causes in adults are diabetes and long-standing high blood pressure; in younger people, autoimmune diseases such as lupus, an immune reaction after a bacterial throat or skin infection, or deposits of immune particles in the kidney. Some chronic viral infections, some medicines and toxins can cause it, and some forms are inherited. In many children the change in the filter is so fine that it shows only under the electron microscope, and it responds excellently to treatment.'
  },
  diagnosis: {
    ar: 'يبدأ الأمر من تحليل البول: وجود بروتين يُقاس بدقّة بنسبة البروتين إلى الكرياتينين في عيّنة، أو بجمع بول أربع وعشرين ساعة، لأن كمية البروتين هي ما يفرّق بين تسريب بسيط ومتلازمة كلائية كاملة. ورؤية كريات حمراء مشوّهة أو أسطوانات حمراء تحت المجهر تدلّ دلالة قويّة على أن مصدر الدم هو الكبيبة لا المثانة. وتُطلب تحاليل دم للبروتين والألبومين والدهون ووظائف الكلى، وتحاليل مناعية تبحث عن ذئبة أو أضداد بعينها، وفحوص لالتهاب الكبد الفيروسي، لأن تسمية السبب تغيّر العلاج كلّه. وقد يحتاج الأمر خزعة كلية، وهي أخذ قطعة صغيرة بإبرة تحت التصوير وفحصها مجهرياً، وهي الفحص الوحيد الذي يسمّي نوع الإصابة بدقّة ويقول هل تُعالج بكبت المناعة أم لا. وعند الأطفال يُؤجَّل هذا غالباً لأن الاستجابة للعلاج تكفي دليلاً.',
    en: 'It begins with the urine test: protein is measured accurately as a protein to creatinine ratio in a sample, or by a twenty-four hour collection, because the amount of protein is what separates a minor leak from a full nephrotic syndrome. Seeing distorted red cells or red cell casts under the microscope points strongly to the glomerulus rather than the bladder as the source of the blood. Blood tests are requested for total protein, albumin, lipids and kidney function, along with immune tests looking for lupus or particular antibodies, and tests for viral hepatitis, because naming the cause changes the whole treatment. A kidney biopsy may be needed, taking a small piece with a needle under imaging and examining it microscopically; it is the only test that names the type of damage precisely and says whether immune suppression is appropriate. In children it is often deferred, because the response to treatment is evidence enough.'
  },
  treatment: {
    ar: 'يسير العلاج في خطّين معاً. الأول علاج السبب: كبت المناعة بأنواع يحدّدها اختصاصي الكلى إذا كان الالتهاب مناعياً، أو علاج العدوى، أو ضبط السكّري ضبطاً صارماً، أو إيقاف الدواء المسبّب. والثاني حماية الكلية مهما كان السبب: خفض ضغط الدم إلى هدف محدّد بأدوية تقلّل أيضاً تسرّب البروتين، وتقليل الملح تقليلاً جدّياً لأنه ما يحبس الماء، ومدرّات بجرعة يوازنها الطبيب لسحب التورّم بلا جفاف، وضبط الدهون، ومتابعة الوزن يومياً كمقياس للسائل. وتُراقَب المضاعفات: من فقد البروتين يفقد أيضاً عوامل تقيه العدوى وأخرى تقيه الجلطات، فيُعطى ما يقي منهما عند الحاجة، وتُستكمل التطعيمات. وأكثر أطفال المتلازمة الكلائية يستجيبون استجابةً كاملة، لكن الانتكاس شائع فتلزم متابعة طويلة وفحص بول دوري في البيت.',
    en: 'Treatment runs along two lines together. The first treats the cause: immune suppression of a kind decided by a kidney specialist if the inflammation is immune, or treating an infection, or strict control of diabetes, or stopping a causative drug. The second protects the kidney whatever the cause: lowering blood pressure to a set target with medicines that also reduce protein leak, a serious reduction in salt because salt is what holds the water, diuretics at a dose balanced by the doctor to draw off the swelling without dehydration, control of blood lipids, and daily weighing as a measure of fluid. Complications are watched: whoever loses protein also loses factors that guard against infection and against clots, so protection is given when needed and vaccinations are completed. Most children with nephrotic syndrome respond completely, but relapse is common, so long follow-up and periodic home urine testing are needed.'
  },
  seeDoctor: {
    ar: 'اذهب للطوارئ إذا ضاق نفسك وأنت مستلقٍ أو ازداد التورّم بسرعة حتى شمل البطن، أو قلّ بولك قلّة واضحة، أو صحب التورّم حمّى وألم بطن، أو ظهر ألم أو تورّم في ساق واحدة أو ألم صدر مفاجئ، فهذه مضاعفات جلطة أو عدوى تصاحب فقد البروتين. واطلب تقييماً عاجلاً إذا صار البول بلون الشاي أو الكولا، أو ارتفع ضغطك ارتفاعاً جديداً مع صداع. واحجز موعداً قريباً إذا لاحظت انتفاخاً في جفنيك صباحاً يتكرّر، أو رغوة كثيفة في البول تبقى بعد السيفون، أو تورّماً في القدمين آخر النهار، ولا تنتظر حتى يعمّ التورّم. ومن عنده سكّري أو ضغط أو ذئبة فتحليل بول للبروتين مرّة في السنة على الأقل ضرورة لا زيادة، لأنه يكشف الأمر قبل أن يشعر به صاحبه بسنوات.',
    en: 'Go to the emergency department if breathing tightens when you lie down or the swelling increases quickly until it involves the abdomen, if urine falls clearly, if the swelling comes with fever and abdominal pain, or if pain or swelling appears in one leg or sudden chest pain occurs, because these are the clot and infection complications that accompany protein loss. Seek urgent assessment if the urine turns the colour of tea or cola, or if blood pressure rises newly with headache. Book an early appointment if you notice repeated morning puffiness of the eyelids, thick froth in the urine that stays after flushing, or swelling of the feet at the end of the day, and do not wait until the swelling becomes general. For anyone with diabetes, high blood pressure or lupus, a urine protein test at least once a year is a necessity rather than an extra, because it reveals the problem years before it is felt.'
  },
  updated: '2026-09-08'
};

DX_BODY['hydronephrosis'] = {
  symptoms: {
    ar: 'تختلف الشكوى اختلافاً كبيراً بحسب سرعة الانسداد. فالانسداد المفاجئ كحصاة تعلق في الحالب يعطي ألماً حادّاً موجيّاً في الخاصرة ينتشر نحو الأربية مع غثيان وقيء، ولا يستقرّ صاحبه على وضعية. أما الانسداد البطيء فقد لا يؤلم إطلاقاً، وهذا هو الخطر: تفقد الكلية وظيفتها في صمت شهوراً وسنين ولا يُكتشف الأمر إلا في صورة أو تحليل. وبينهما صورة ثالثة: ثقل مبهم أو ألم خفيف في الخاصرة يزداد بعد شرب كمية كبيرة من السوائل. وقد تظهر علامات غير مباشرة: التهابات مسالك متكرّرة، وارتفاع ضغط، ودم في البول، وضعف رفيق البول أو تقطّعه أو إحساس بأن المثانة لا تفرغ إن كان الانسداد أسفل. وعند الرضّع قد يكون العرض الوحيد كتلة تُحسّ في البطن أو حمّى متكرّرة بلا سبب.',
    en: 'The complaint differs greatly with the speed of the blockage. A sudden block such as a stone caught in the ureter gives sharp pain in waves in the flank spreading toward the groin with nausea and vomiting, and the person cannot settle in any position. A slow block may not hurt at all, and that is the danger: the kidney loses its function silently over months and years and the matter is only found on a scan or a blood test. Between the two lies a third picture: vague heaviness or mild flank pain that increases after drinking a large volume. Indirect signs may appear: repeated urinary infections, high blood pressure, blood in the urine, and a weak or interrupted stream or a sense that the bladder does not empty if the block is low down. In infants the only sign may be a mass felt in the abdomen or repeated unexplained fever.'
  },
  cause: {
    ar: 'كل ما يقف في طريق البول بعد الكلية يرفع الضغط إليها فيوسّع حويضتها وكؤوسها. وأشيع الأسباب حصاة في الحالب، ثم تضخّم البروستاتا الذي يمنع المثانة من التفريغ فيرتدّ الضغط إلى الكليتين معاً، ثم تضيّق الحالب من ندبة بعد عملية أو التهاب أو إشعاع. ويوجد عند بعض الناس ضيق خلقي في موضع اتصال الحويضة بالحالب يظهر في الطفولة أو يتأخّر إلى الكبر. وعند الأطفال سبب مهمّ آخر هو ارتداد البول من المثانة صاعداً في الحالب لخلل في صمّامه، فيصعد معه الالتهاب. وتضغط الحالبين من الخارج أورام الحوض وتضخّم العقد وتليّف خلف الصفاق، ويضغطهما الرحم في الحمل ضغطاً غالباً ما يكون بلا ضرر ويزول بعد الولادة. وقد يكون السبب عصبياً: مثانة لا تنقبض أو لا ترتخي فلا تفرغ.',
    en: 'Anything standing in the path of urine below the kidney raises pressure back into it, widening its pelvis and calyces. The commonest cause is a stone in the ureter, then an enlarged prostate that stops the bladder emptying so pressure backs up into both kidneys, then narrowing of the ureter from scarring after surgery, inflammation or radiotherapy. Some people have a congenital narrowing where the renal pelvis joins the ureter, appearing in childhood or later in life. In children another important cause is reflux of urine from the bladder up the ureter through a faulty valve, carrying infection upward with it. The ureters may be compressed from outside by pelvic tumours, enlarged nodes or fibrosis behind the abdominal lining, and by the womb in pregnancy, which is usually harmless and resolves after delivery. The cause may also be neurological: a bladder that does not contract or does not relax, so it never empties.'
  },
  diagnosis: {
    ar: 'الموجات الصوتية هي أول فحص وأسرعه وأكثره أماناً، وتُظهر توسّع الحويضة والكؤوس وتقدّر درجته، وتُفضَّل عند الحوامل والأطفال لخلوّها من الإشعاع. والأشعة المقطعية تجيب عن السؤال الأهمّ بعد ذلك: أين موضع الانسداد وما سببه بالضبط، وهي المعيار عند الشكّ في حصاة. ويُقاس بعدها البول المتبقّي في المثانة بعد التبوّل بموجات صوتية بسيطة، لأن بقاء كمية كبيرة يدلّ على أن الانسداد أسفل المثانة لا في الحالب، وهذا يغيّر العلاج كلّياً. ويُطلب تحليل بول وزرع بحثاً عن عدوى، وتحاليل دم لوظائف الكلى. وإن كان السؤال هل ما زالت الكلية تعمل ويستحقّ إنقاذها، فمسح نووي للكلى هو ما يقيس نصيب كل كلية من الوظيفة ويقيس تصريفها، وعليه يُبنى قرار الجراحة من عدمه.',
    en: 'Ultrasound is the first, fastest and safest test, showing the widened pelvis and calyces and grading the degree, and it is preferred in pregnancy and children because it uses no radiation. A CT scan then answers the more important question: where exactly the block lies and what is causing it, and it is the standard when a stone is suspected. The urine left in the bladder after passing water is then measured with simple ultrasound, because a large residue shows the block is below the bladder rather than in the ureter, which changes the treatment entirely. A urine test and culture are requested to look for infection, with blood tests for kidney function. If the question is whether the kidney still works and is worth saving, a nuclear kidney scan measures the share of function of each kidney and how well it drains, and the decision to operate rests on it.'
  },
  treatment: {
    ar: 'القاعدة أن تصريف البول يسبق كل شيء إذا كانت الكلية مسدودة ومصابة بعدوى أو كانت الوظيفة تنهار، ولا يُنتظر معها نتيجة تحليل ولا استجابة لمضاد حيوي، لأن الضغط والقيح معاً يتلفان النسيج بسرعة. والتصريف إمّا بدعامة تُمرَّر داخل الحالب من المثانة، وإمّا بأنبوب يُدخَل إلى الكلية عبر جلد الظهر حين يتعذّر الأول. ثم يُعالَج السبب على مهل بعد أن يهدأ الخطر: تفتيت الحصاة أو استخراجها، أو علاج تضخّم البروستاتا، أو توسيع التضيّق أو استئصاله وإعادة توصيل الحالب جراحياً، أو تفريغ المثانة بقسطرة متقطّعة إن كان السبب عصبياً. وعند الرضّع كثير من حالات التوسّع الخفيف تتحسّن وحدها مع النمو ولا تحتاج إلا متابعة بالموجات الصوتية. وبعد أي علاج تُعاد الصور والوظائف للتأكد أن التصريف رجع فعلاً.',
    en: 'The rule is that drainage comes before everything if the kidney is blocked and infected or if function is collapsing; no one waits for a test result or for an antibiotic to work, because pressure and pus together destroy the tissue quickly. Drainage is either by a stent passed up the ureter from the bladder, or by a tube placed into the kidney through the skin of the back when the first is not possible. The cause is then treated at leisure once the danger has passed: breaking or removing the stone, treating the enlarged prostate, dilating or excising the narrowing and rejoining the ureter surgically, or emptying the bladder with intermittent catheterisation if the cause is neurological. In infants many mild dilatations improve on their own with growth and need only ultrasound follow-up. After any treatment, imaging and function tests are repeated to confirm that drainage has truly returned.'
  },
  seeDoctor: {
    ar: 'اذهب إلى الطوارئ فوراً إذا اجتمع ألم الخاصرة مع حمّى ورجفة، فهذه كلية مسدودة وملتهبة معاً وهي حالة تُصرَّف في ساعات لا في أيام. واطلب الإسعاف إذا قلّ بولك قلّة شديدة أو انقطع، أو صحب ذلك قيء متواصل أو تشوّش أو هبوط، خصوصاً إن كانت لك كلية واحدة. واذهب للطوارئ أيضاً إذا عجزت عن التبوّل مع امتلاء مؤلم أسفل البطن. واحجز موعداً قريباً إذا تكرّرت التهابات المسالك، أو ضعف رفيق البول أو تقطّع، أو بقي إحساس بأن المثانة لم تفرغ، أو ظهر ألم خفيف متكرّر في الخاصرة يزيد بعد شرب كثير. ومن قيل له في صورة سابقة إن عنده توسّعاً في الكلية ولو بلا أعراض فلا يهمله: يحتاج متابعة تقول هل الوظيفة ثابتة أم تتراجع بصمت.',
    en: 'Go to the emergency department at once if flank pain comes together with fever and chills, because this is a kidney that is both blocked and infected, and it is drained within hours rather than days. Call an ambulance if your urine falls severely or stops, or if this comes with persistent vomiting, confusion or collapse, especially if you have a single kidney. Go to the emergency department also if you cannot pass urine at all with painful fullness in the lower abdomen. Book an early appointment if urinary infections recur, if the stream weakens or is interrupted, if a sense remains that the bladder has not emptied, or if a mild recurring flank pain appears that worsens after drinking a lot. Anyone told on a previous scan that there is dilatation of a kidney, even without symptoms, should not ignore it: follow-up is needed to say whether the function is stable or quietly declining.'
  },
  updated: '2026-09-08'
};

